package dev.smokekitchen.test;

import dev.smokekitchen.content.KitchenContent;
import dev.smokekitchen.world.KitchenCropBlock;
import dev.smokekitchen.world.KitchenWildCrops;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.core.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.level.levelgen.presets.WorldPresets;
import net.minecraft.world.phys.*;

/** Natural seed-1 terrain and untouched generated plants; tools and bone meal are test supplies.
 * Teleportation is for locating specimens, so this is NOT the separate from-zero survival acceptance. */
public final class EcologyFlowTest implements FabricClientGameTest {
    private static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
    private static void equip(ClientGameTestContext c,TestServerContext s,String item){c.runOnClient(client->{client.player.getInventory().setSelectedSlot(8);if(!client.player.getMainHandItem().isEmpty())client.gameMode.handleContainerInput(client.player.inventoryMenu.containerId,44,0,net.minecraft.world.inventory.ContainerInput.QUICK_MOVE,client.player);});c.waitTicks(3);s.runCommand("item replace entity @a hotbar.8 with "+item);c.waitTicks(4);}
    private static void select(ClientGameTestContext c,String item){c.runOnClient(client->{for(int i=0;i<36;i++)if(client.player.getInventory().getItem(i).is(KitchenContent.item(item))){if(i>8){client.gameMode.handleContainerInput(client.player.inventoryMenu.containerId,i,7,net.minecraft.world.inventory.ContainerInput.SWAP,client.player);client.player.getInventory().setSelectedSlot(7);}else client.player.getInventory().setSelectedSlot(i);return;}throw new AssertionError("Actual harvested item missing: "+item);});c.waitTicks(4);}
    private static void travel(ClientGameTestContext c,TestServerContext s,BlockPos pos){s.runCommand("tp @a "+(pos.getX()+.5)+" "+(pos.getY()+.1)+" "+(pos.getZ()+.5)+" 0 65");c.waitTicks(12);}
    private static void click(ClientGameTestContext c,BlockPos pos){c.runOnClient(client->client.gameMode.useItemOn(client.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false)));c.waitTicks(6);}
    private static void harvest(ClientGameTestContext c,TestServerContext s,BlockPos pos){equip(c,s,"minecraft:air");travel(c,s,pos);c.runOnClient(client->client.gameMode.startDestroyBlock(pos,Direction.UP));c.waitTicks(5);c.runOnClient(client->client.gameMode.stopDestroyBlock());c.waitTicks(15);}
    private static void photograph(ClientGameTestContext c,TestServerContext s,TestSingleplayerContext world,BlockPos pos,String name){BlockPos[] view={pos.north(2)};s.runOnServer(g->{double best=100;for(int dx=-3;dx<=3;dx++)for(int dz=-3;dz<=3;dz++)for(int dy=0;dy<=2;dy++){double distance=dx*dx+dz*dz+dy*dy;if(distance<4||distance>=best)continue;var candidate=pos.offset(dx,dy,dz);var ground=g.overworld().getBlockState(candidate.below());if((ground.is(Blocks.GRASS_BLOCK)||ground.is(Blocks.DIRT)||ground.is(Blocks.SAND))&&g.overworld().isEmptyBlock(candidate)&&g.overworld().isEmptyBlock(candidate.above())){view[0]=candidate;best=distance;}}});travel(c,s,view[0]);world.getClientLevel().waitForChunksRender();c.runOnClient(client->{var delta=Vec3.atCenterOf(pos).subtract(client.player.getEyePosition());client.player.setYRot((float)(Math.toDegrees(Math.atan2(delta.z,delta.x))-90));client.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.x*delta.x+delta.z*delta.z))));client.getToastManager().clear();});c.waitTicks(12);c.takeScreenshot(name);}
    private static BlockPos findWild(ClientGameTestContext c,TestServerContext s,String crop) {
        BlockPos[] center={null},found={null};s.runOnServer(g->{var match=g.overworld().findClosestBiome3d(KitchenWildCrops.HABITATS.get(crop)::matches,new BlockPos(0,64,0),2048,32,64);check(match!=null,"Natural world must contain the specified habitat for "+crop);center[0]=match.getFirst();});
        for(int radius=0;radius<=9;radius++)for(int dx=-radius;dx<=radius;dx++)for(int dz=-radius;dz<=radius;dz++) {
            if(radius>0&&Math.abs(dx)!=radius&&Math.abs(dz)!=radius)continue;
            int cx=(center[0].getX()>>4)+dx,cz=(center[0].getZ()>>4)+dz;
            s.runOnServer(g->{var level=g.overworld();level.getChunk(cx,cz);var block=KitchenContent.CROPS.get(crop);for(int x=cx*16;x<cx*16+16&&found[0]==null;x++)for(int z=cz*16;z<cz*16+16&&found[0]==null;z++){int top=level.getHeight(Heightmap.Types.WORLD_SURFACE,x,z);for(int y=top;y>=top-33;y--){var pos=new BlockPos(x,y,z);var state=level.getBlockState(pos);if(state.is(block)&&state.getValue(KitchenCropBlock.WILD)){check(state.canSurvive(level,pos),"Generated plant must survive on its actual natural ground: "+crop);found[0]=pos;break;}}}});c.waitTicks(1);
            if(found[0]!=null){org.slf4j.LoggerFactory.getLogger("SmokeKitchenEcology").info("Natural seed 1 specimen {} at {}",crop,found[0]);return found[0];}
        }
        throw new AssertionError("No naturally generated "+crop+" around its habitat "+center[0]);
    }
    @Override public void runTest(ClientGameTestContext c) {
        c.runOnClient(client->client.options.guiScale().set(2));TestWorldSave save;BlockPos[] saved={null,null,null};int[] savedAge={0};
        try(var world=c.worldBuilder().adjustSettings(ui->{ui.setWorldType(ui.getNormalPresetList().stream().filter(p->p.preset().is(WorldPresets.NORMAL)).findFirst().orElseThrow());ui.setSeed("1");}).create()) {
            save=world.getWorldSave();var s=world.getServer();s.runCommand("gamemode survival @a");s.runCommand("time set day");s.runCommand("weather clear");c.waitTicks(10);
            if(net.fabricmc.loader.api.FabricLoader.getInstance().isModLoaded("iris"))c.runOnClient(client->{try{var api=Class.forName("net.irisshaders.iris.api.v0.IrisApi");check((Boolean)api.getMethod("isShaderPackInUse").invoke(api.getMethod("getInstance").invoke(null)),"The ecology shader run must actually use its shader pack");}catch(ReflectiveOperationException e){throw new AssertionError(e);}});
            var rice=findWild(c,s,"rice_paddy");saved[0]=rice;photograph(c,s,world,rice,"ecology-natural-river-rice-0.1.9");harvest(c,s,rice);
            s.runOnServer(g->{var inv=g.getPlayerList().getPlayers().getFirst().getInventory();check(inv.countItem(KitchenContent.item("rice_paddy"))>=2&&inv.countItem(KitchenContent.item("rice_paddy_seeds"))>=2,"Actual untouched wild rice must drop grain and expandable seed");check(!g.overworld().getBlockState(rice.below()).is(Blocks.FARMLAND),"Natural wild rice must not convert the riverbank into a farm");});
            equip(c,s,"minecraft:wooden_hoe");click(c,rice.below());select(c,"rice_paddy_seeds");click(c,rice.below());s.runOnServer(g->check(g.overworld().getBlockState(rice).is(KitchenContent.CROPS.get("rice_paddy"))&&!g.overworld().getBlockState(rice).getValue(KitchenCropBlock.WILD),"A real harvested seed must replant as a cultivated rice seedling"));
            equip(c,s,"minecraft:bone_meal 6");for(int i=0;i<4;i++)click(c,rice);s.runOnServer(g->check(KitchenContent.CROPS.get("rice_paddy").isMaxAge(g.overworld().getBlockState(rice)),"Ordinary bone meal must mature properly irrigated rice"));photograph(c,s,world,rice,"ecology-cultivated-rice-0.1.9");harvest(c,s,rice);select(c,"rice_paddy_seeds");click(c,rice.below());equip(c,s,"minecraft:bone_meal 6");click(c,rice);s.runOnServer(g->savedAge[0]=KitchenContent.CROPS.get("rice_paddy").getAge(g.overworld().getBlockState(rice)));
            var tomato=findWild(c,s,"tomato");saved[1]=tomato;photograph(c,s,world,tomato,"ecology-natural-plains-tomato-0.1.9");harvest(c,s,tomato);select(c,"tomato_seeds");click(c,tomato.below());s.runOnServer(g->check(g.overworld().isEmptyBlock(tomato),"Harvested seeds must not recreate wild crops on untreated grass"));equip(c,s,"minecraft:wooden_hoe");click(c,tomato.below());select(c,"tomato_seeds");click(c,tomato.below());s.runOnServer(g->check(g.overworld().getBlockState(tomato).is(KitchenContent.CROPS.get("tomato"))&&!g.overworld().getBlockState(tomato).getValue(KitchenCropBlock.WILD),"Tilling must enable ordinary tomato cultivation"));
            s.runOnServer(g->{for(int dx=-8;dx<=8&&saved[2]==null;dx++)for(int dz=-8;dz<=8;dz++){int x=tomato.getX()+dx,z=tomato.getZ()+dz,y=g.overworld().getHeight(Heightmap.Types.WORLD_SURFACE,x,z);var pos=new BlockPos(x,y,z);if(g.overworld().getBlockState(pos.below()).is(Blocks.GRASS_BLOCK)&&g.overworld().isEmptyBlock(pos)&&!KitchenCropBlock.nearWater(g.overworld(),pos)){saved[2]=pos;break;}}check(saved[2]!=null,"Natural plains must supply a dry cultivation comparison");});travel(c,s,saved[2]);equip(c,s,"minecraft:wooden_hoe");click(c,saved[2].below());select(c,"rice_paddy_seeds");click(c,saved[2].below());equip(c,s,"minecraft:bone_meal 6");for(int i=0;i<3;i++)click(c,saved[2]);s.runOnServer(g->check(g.overworld().getBlockState(saved[2]).is(KitchenContent.CROPS.get("rice_paddy"))&&KitchenContent.CROPS.get("rice_paddy").getAge(g.overworld().getBlockState(saved[2]))==0&&g.getPlayerList().getPlayers().getFirst().getMainHandItem().getCount()==6,"Real client bone meal must neither grow dry rice nor be consumed"));photograph(c,s,world,saved[2],"ecology-dry-rice-does-not-grow-0.1.9");
            var mushroom=findWild(c,s,"shiitake");photograph(c,s,world,mushroom,"ecology-natural-shaded-shiitake-0.1.9");harvest(c,s,mushroom);s.runOnServer(g->check(g.getPlayerList().getPlayers().getFirst().getInventory().countItem(KitchenContent.item("shiitake"))>=2,"A naturally generated shaded mushroom must actually be harvestable"));
            travel(c,s,rice);equip(c,s,"smoke_kitchen:recipe_book");c.runOnClient(client->client.gameMode.useItem(client.player,InteractionHand.MAIN_HAND));c.waitTicks(5);for(int i=0;i<20;i++){boolean[] at={false};c.runOnClient(client->{try{var screen=client.screen;var field=screen.getClass().getDeclaredField("renderedPages");field.setAccessible(true);var index=screen.getClass().getDeclaredField("page");index.setAccessible(true);var p=((java.util.List<?>)field.get(screen)).get(index.getInt(screen));var title=p.getClass().getDeclaredMethod("title");title.setAccessible(true);at[0]="野生作物与留种".equals(title.invoke(p));if(!at[0])for(var child:screen.children())if(child instanceof net.minecraft.client.gui.components.Button button&&button.getMessage().getString().equals("下一页")){button.onPress(null);break;}}catch(ReflectiveOperationException e){throw new AssertionError(e);}});c.waitTicks(3);if(at[0]){c.runOnClient(client->client.getToastManager().clear());c.takeScreenshot("ecology-growing-guide-0.1.9");break;}check(i<19,"Actual ecology guide must be reachable");}c.runOnClient(client->client.setScreen(null));
        }
        try(var world=save.open()){c.waitTicks(10);world.getServer().runOnServer(g->{var state=g.overworld().getBlockState(saved[0]);check(state.is(KitchenContent.CROPS.get("rice_paddy"))&&!state.getValue(KitchenCropBlock.WILD)&&KitchenContent.CROPS.get("rice_paddy").getAge(state)>=savedAge[0],"Cultivated rice age and natural/cultivated identity must survive actual reopening");check(g.overworld().getBlockState(saved[2]).is(KitchenContent.CROPS.get("rice_paddy"))&&KitchenContent.CROPS.get("rice_paddy").getAge(g.overworld().getBlockState(saved[2]))==0,"A dry seedling must remain paused after saving and reloading");var inv=g.getPlayerList().getPlayers().getFirst().getInventory();check(inv.countItem(KitchenContent.item("rice_paddy"))>=4&&inv.countItem(KitchenContent.item("tomato"))>=2&&inv.countItem(KitchenContent.item("shiitake"))>=2,"Actual natural harvests must survive saving without replacing them with fixture products");});world.getClientLevel().waitForChunksRender();c.takeScreenshot("ecology-after-world-reopen-0.1.9");}
    }
}
